package com.becon.opencelium.backend.security.oidc;

public interface OidcLoginService {

    /**
     * A client nonce shorter than this is refused: the binding to the browser is only as good as the
     * value the frontend keeps, and a constant would make it worthless.
     */
    int MIN_CLIENT_NONCE_LENGTH = 16;

    /**
     * Prepares the redirect to the identity provider and the values that must be kept until the
     * callback arrives. 'clientNonce' is generated by the frontend; only its hash is kept, so that
     * the one-time ticket can later be handed back by the same browser.
     */
    Start beginLogin(String clientNonce);

    /**
     * Validates the callback parameters against the values kept from {@link #beginLogin(String)} and
     * returns the verified identity of the user.
     */
    OidcIdentity completeLogin(String code, String state, OidcAuthorizationState expected);

    /**
     * Issues a single-use ticket that the frontend exchanges for an OpenCelium session. The hash of
     * the client nonce travels with it, because /oidc/exchange is reachable from any browser.
     */
    String issueTicket(OidcIdentity identity, String clientNonceHash);

    /**
     * Consumes the ticket if it is fresh, unused and was issued to a browser that presents the same
     * client nonce.
     */
    OidcIdentity consumeTicket(String ticket, String clientNonce);

    record Start(OidcAuthorizationState state, String authorizationUri) {
    }
}
